var registry = map[string]Importer{}

// Register adds an importer keyed by its Name. Intended for init() in each
// agent implementation. Panics on duplicate registration (programmer error).
func Register(imp Importer) {
	name := imp.Name()
	if _, exists := registry[name]; exists {
		panic("agentimport: duplicate importer " + name)
	}
	registry[name] = imp
}

// Get returns the importer registered under name.
func Get(name string) (Importer, bool) {
	imp, ok := registry[name]
	return imp, ok
}

// All returns every registered importer, sorted by name.
func All() []Importer {
	out := make([]Importer, 0, len(registry))
	for _, imp := range registry {
		out = append(out, imp)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name() < out[j].Name() })
	return out
}

